#include <stdio.h>
#include <stdlib.h>

#define INF 0x3f3f3f3f3f3f3f3fLL

typedef struct {
    int u;
    int t;
    int id;
} NodeKey;

int cmp_nodekey(const void *a, const void *b) {
    const NodeKey *ka = (const NodeKey *)a;
    const NodeKey *kb = (const NodeKey *)b;
    if (ka->u != kb->u) return (ka->u < kb->u) ? -1 : 1;
    if (ka->t != kb->t) return (ka->t < kb->t) ? -1 : 1;
    return 0;
}

int find_id(const NodeKey *arr, int size, int u, int t) {
    int l = 0, r = size - 1;
    while (l <= r) {
        int m = l + (r - l) / 2;
        if (arr[m].u == u && arr[m].t == t) return arr[m].id;
        if (arr[m].u < u || (arr[m].u == u && arr[m].t < t)) {
            l = m + 1;
        } else {
            r = m - 1;
        }
    }
    return -1;
}

