int heap_size = 0;

void heap_push(int u, long long dist) {
    int i = heap_size++;
    heap[i].u = u;
    heap[i].dist = dist;
    while (i > 0) {
        int p = (i - 1) / 2;
        if (heap[p].dist <= heap[i].dist) break;
        HeapNode tmp = heap[p];
        heap[p] = heap[i];
        heap[i] = tmp;
        i = p;
    }
}

HeapNode heap_pop(void) {
    HeapNode min_node = heap[0];
    heap_size--;
    if (heap_size > 0) {
        heap[0] = heap[heap_size];
        int i = 0;
        while (2 * i + 1 < heap_size) {
            int left = 2 * i + 1;
            int right = 2 * i + 2;
            int best = left;
            if (right < heap_size && heap[right].dist < heap[left].dist) {
                best = right;
